const starter=[{id:'vector-shell',name:'Куртка Vector Shell',category:'Куртки',price:24900,priceLabel:'24 900 ₽',color:'#77818a',tag:'NEW'},{id:'core-layer',name:'Худи / Core Layer',category:'Футболки',price:8900,priceLabel:'8 900 ₽',color:'#d7d0c2',tag:'01'},{id:'transit-wide',name:'Брюки Transit Wide',category:'Брюки',price:12900,priceLabel:'12 900 ₽',color:'#af8972',tag:'NEW'},{id:'cross-01',name:'Кроссовки Cross-01',category:'Обувь',price:18900,priceLabel:'18 900 ₽',color:'#aab8bd',tag:'01'}];
const products=()=>JSON.parse(localStorage.getItem('instakross-products')||'null')||starter;const orders=()=>JSON.parse(localStorage.getItem('instakross-orders')||'[]');const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const banner=document.createElement('div');banner.style.cssText='background:#e6ebff;color:#18215a;padding:14px 18px;margin-bottom:24px;font:12px Manrope;display:flex;justify-content:space-between;gap:15px;align-items:center';document.querySelector('main').prepend(banner);
function render(q=''){const data=products().filter(p=>p.name.toLowerCase().includes(q.toLowerCase()));document.querySelector('#productCount').textContent=products().length;document.querySelector('#adminTable').innerHTML='<div class="table-row head"><span>Название</span><span>Категория</span><span>Цена</span><span>Статус</span></div>'+data.map(p=>`<div class="table-row"><strong>${p.name}</strong><span>${p.category}</span><span>${p.priceLabel||money(p.price||0)}</span><span class="tag">● В каталоге</span></div>`).join('');const box=document.querySelector('#ordersTable');if(box){const os=orders();box.innerHTML=os.length?os.slice(-5).reverse().map(o=>`<div class="table-row"><strong>${o.id}</strong><span>${o.customer?.name||'—'}</span><span>${money(o.total)}</span><span class="tag">● ${o.status}</span></div>`).join(''):'<p class="muted">Заказы появятся после оформления покупки.</p>'}}
async function checkOwner(){try{const r=await fetch('/api/admin/products');if(r.status===401){banner.innerHTML='<span>Вход в админку</span><form id="loginForm" style="display:flex;gap:8px;flex-wrap:wrap"><input id="loginInput" type="email" placeholder="Логин" required style="padding:9px;border:1px solid #cdd2e2"><input id="passwordInput" type="password" placeholder="Пароль" required style="padding:9px;border:1px solid #cdd2e2"><button type="submit" style="background:#1e43ee;color:#fff;border:0;padding:9px 13px;font-weight:700">Войти</button></form><a href="/signin-with-chatgpt?return_to=/admin.html" target="_top" style="color:#1e43ee">или войти через ChatGPT</a>';document.querySelector('#loginForm').onsubmit=async ev=>{ev.preventDefault();const rr=await fetch('/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({login:document.querySelector('#loginInput').value,password:document.querySelector('#passwordInput').value})});if(rr.ok){await checkOwner()}else{banner.querySelector('span').textContent='Неверный логин или пароль'}};return}if(r.ok){const rows=await r.json();if(rows.length){localStorage.setItem('instakross-products',JSON.stringify(rows.map(p=>({id:p.id,name:p.name,category:p.category_id,price:Number(p.price_cents||0)/100,priceLabel:money(Number(p.price_cents||0)/100),color:p.color||'#77818a',tag:'NEW'}))));render()}banner.textContent='Доступ подтверждён. Вы вошли как администратор.';banner.style.background='#e5f4e9';banner.style.color='#174d2a'}}catch{banner.textContent='Серверная проверка временно недоступна.'}}
render();checkOwner();document.querySelector('#adminSearch').addEventListener('input',e=>render(e.target.value));const modal=document.querySelector('#modal');document.querySelector('#openForm').onclick=()=>modal.classList.add('open');document.querySelector('#closeForm').onclick=()=>modal.classList.remove('open');document.querySelector('#productForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const payload={name:d.name,slug:(d.name||'product').toLowerCase().replace(/[^a-zа-я0-9]+/gi,'-'),category_id:{'Куртки':'outerwear','Футболки':'tops','Брюки':'bottoms','Обувь':'footwear','Аксессуары':'accessories'}[d.category]||'outerwear',price_cents:Number(String(d.price).replace(/\D/g,''))*100,color:d.color,stock:0,sizes:['S','M','L','XL']};let saved=false;try{const r=await fetch('/api/admin/products',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});saved=r.ok}catch{}if(!saved){const arr=[...products(),{id:'product-'+Date.now(),name:d.name,category:d.category,price:payload.price_cents/100,priceLabel:money(payload.price_cents/100),color:d.color,tag:'NEW'}];localStorage.setItem('instakross-products',JSON.stringify(arr))}render();modal.classList.remove('open');e.target.reset()};
